select tablename, policyname, cmd, roles, qual, with_check from pg_policies where schemaname = 'public' and tablename in ('organizations', 'chat_presence', 'availability', 'setlist_items') order by tablename, cmd, policyname;
select c.relname as tabla, c.relrowsecurity as rls, has_table_privilege('anon', c.oid, 'select') as anon_select, has_table_privilege('anon', c.oid, 'insert') as anon_insert, has_table_privilege('anon', c.oid, 'update') as anon_update, has_table_privilege('anon', c.oid, 'delete') as anon_delete from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relname in ('organizations', 'chat_presence', 'availability', 'setlist_items') order by 1;
do $$ declare sid uuid; mc uuid; ma uuid; r text := ''; n int; imp uuid := '00000000-0000-0000-0000-00000000dead'; begin
select id into sid from public.services limit 1;
select m.id into mc from public.members m where not exists (select 1 from public.chat_presence c where c.member_id = m.id) limit 1;
select m.id into ma from public.members m where sid is not null and not exists (select 1 from public.availability a where a.member_id = m.id and a.service_id = sid) limit 1;
set local role anon;
begin select count(*) into n from public.organizations; r := r || 'FALLO: anon lee organizations (' || n || ' filas); '; exception when insufficient_privilege then r := r || 'OK: anon no lee organizations; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
begin select count(*) into n from public.chat_presence; r := r || 'FALLO: anon lee chat_presence (' || n || ' filas); '; exception when insufficient_privilege then r := r || 'OK: anon no lee chat_presence; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
begin select count(*) into n from public.availability; r := r || 'FALLO: anon lee availability (' || n || ' filas); '; exception when insufficient_privilege then r := r || 'OK: anon no lee availability; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
begin select count(*) into n from public.setlist_items; r := r || 'FALLO: anon lee setlist_items (' || n || ' filas); '; exception when insufficient_privilege then r := r || 'OK: anon no lee setlist_items; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
begin insert into public.organizations (nombre, slug) values ('prueba', 'prueba-053b'); r := r || 'FALLO: anon insertó en organizations; '; exception when insufficient_privilege then r := r || 'OK: anon no inserta en organizations; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
begin update public.organizations set nombre = nombre where id = imp; r := r || 'FALLO: anon pudo actualizar organizations; '; exception when insufficient_privilege then r := r || 'OK: anon no actualiza organizations; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
begin delete from public.organizations where id = imp; r := r || 'FALLO: anon pudo borrar en organizations; '; exception when insufficient_privilege then r := r || 'OK: anon no borra en organizations; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
if mc is not null then begin insert into public.chat_presence (member_id, chat_id) values (mc, 'prueba'); r := r || 'FALLO: anon insertó en chat_presence; '; exception when insufficient_privilege then r := r || 'OK: anon no inserta en chat_presence; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end; else r := r || 'OMITIDO: no hay una persona sin presencia para probar el insert en chat_presence; '; end if;
begin update public.chat_presence set chat_id = chat_id where member_id = imp; r := r || 'FALLO: anon pudo actualizar chat_presence; '; exception when insufficient_privilege then r := r || 'OK: anon no actualiza chat_presence; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
begin delete from public.chat_presence where member_id = imp; r := r || 'FALLO: anon pudo borrar en chat_presence; '; exception when insufficient_privilege then r := r || 'OK: anon no borra en chat_presence; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
if ma is not null then begin insert into public.availability (member_id, service_id) values (ma, sid); r := r || 'FALLO: anon insertó en availability; '; exception when insufficient_privilege then r := r || 'OK: anon no inserta en availability; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end; else r := r || 'OMITIDO: no hay datos para probar el insert en availability; '; end if;
begin update public.availability set status = status where id = imp; r := r || 'FALLO: anon pudo actualizar availability; '; exception when insufficient_privilege then r := r || 'OK: anon no actualiza availability; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
begin delete from public.availability where id = imp; r := r || 'FALLO: anon pudo borrar en availability; '; exception when insufficient_privilege then r := r || 'OK: anon no borra en availability; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
if sid is not null then begin insert into public.setlist_items (service_id, orden) values (sid, 9999); r := r || 'FALLO: anon insertó en setlist_items; '; exception when insufficient_privilege then r := r || 'OK: anon no inserta en setlist_items; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end; else r := r || 'OMITIDO: no hay un servicio para probar el insert en setlist_items; '; end if;
begin update public.setlist_items set orden = orden where id = imp; r := r || 'FALLO: anon pudo actualizar setlist_items; '; exception when insufficient_privilege then r := r || 'OK: anon no actualiza setlist_items; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
begin delete from public.setlist_items where id = imp; r := r || 'FALLO: anon pudo borrar en setlist_items; '; exception when insufficient_privilege then r := r || 'OK: anon no borra en setlist_items; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
reset role;
raise exception 'Resultado (se deshace todo): %', r; end $$;
